        scores.append(sum(
            grid[r][c] != outside
            and (c == 0 or grid[r][c - 1] == outside)
            and (c == w - 1 or grid[r][c + 1] == outside)
            for c in range(w)
        ))
    key_row = max(range(h), key=lambda r: scores[r])

    seq = [
        grid[key_row][c]
        for c in range(w)
        if grid[key_row][c] != outside
        and (c == 0 or grid[key_row][c - 1] == outside)
        and (c == w - 1 or grid[key_row][c + 1] == outside)
    ]
    palette = set(seq)

    # Extract colored objects; exclude the isolated markers in the key row.
    seen = set()
    objects = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color not in palette or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and
                            (ny, nx) not in seen and grid[ny][nx] == color):
                        seen.add((ny, nx))
                        stack.append((ny, nx))
            if all(y == key_row for y, x in cells):
                continue
            ys = [y for y, x in cells]
            xs = [x for y, x in cells]
            objects.append((color, min(ys), max(ys), min(xs), max(xs)))

    def direction(a, b):
        # Return horizontal or vertical when the object centers line up.
        if a[1] + a[2] == b[1] + b[2]:
            return "h"
        if a[3] + a[4] == b[3] + b[4]:
            return "v"
        return None

    chain = []

