                continue
            if chain and direction(chain[-1], obj) is None:
                continue
            chain.append(obj)
            used.add(j)
            if search(i + 1, used):
                return True
            used.remove(j)
            chain.pop()
        return False

    search(0, set())
    out = [row[:] for row in grid]

    for a, b in zip(chain, chain[1:]):
        color = a[0]
        d = direction(a, b)
        if d == "h":
            left, right = sorted((a, b), key=lambda o: o[3])
            y0, y1 = max(a[1], b[1]), min(a[2], b[2])
            for y in range(y0, y1 + 1):
                for x in range(left[4] + 1, right[3]):
                    if grid[y][x] == outside:
                        out[y][x] = color
        elif d == "v":
            top, bottom = sorted((a, b), key=lambda o: o[1])
            x0, x1 = max(a[3], b[3]), min(a[4], b[4])
            for y in range(top[2] + 1, bottom[1]):
                for x in range(x0, x1 + 1):
                    if grid[y][x] == outside:
                        out[y][x] = color

    return out
